      "mimeType": "application/yaml",
      "text": "interface:\n  display_name: \"Signal\"\n  short_description: \"Check visibility, investigate weaknesses and compare changes\"\n  default_prompt: \"Check my website's AI discoverability, then offer the sourced ten-question sample.\"\n\ndependencies:\n  tools:\n    - type: \"mcp\"\n      value: \"aido-discoverability-check\"\n      description: \"Public website evidence and saved Signal visibility studies\"\n      transport: \"streamable_http\"\n      url: \"https://mcp.sr3h.uk/mcp\"\n\npolicy:\n  allow_implicit_invocation: true\n"
